export function translate(text: string, locale: Locale): string {
  const normalized = text.trim().toLowerCase();
  if (locale === 'ar') return normalizedEnglishToArabic.get(normalized) ?? text;
  const direct = translations[text];
  if (direct) return direct;
  return normalizedEnumTranslations.get(normalized) ?? text;
}

export function translateEnum(value: string | null | undefined, locale: Locale): string {
  if (value == null || value === '') return value ?? '';
  if (locale === 'ar') {
    const normalized = value.trim().toLowerCase().replace(/[ -]+/gu, '_');
    return enumArabicTranslations[normalized] ?? normalizedEnglishToArabic.get(value.trim().toLowerCase()) ?? value;
  }
  return translate(value, locale);
}

export function applyLocale(locale: Locale) {
  document.documentElement.lang = locale;
  document.documentElement.dir = locale === 'ar' ? 'rtl' : 'ltr';
  try {
    localStorage.setItem('alqirsh-language', locale);
    document.cookie = `alqirsh-language=${locale}; path=/; max-age=31536000; SameSite=Lax`;
  } catch {}
}
